import test from 'node:test';import assert from 'node:assert/strict';import {validateReviews} from '../../reviews.mjs';
const raw={rating:{source:'VERIFIED_ORDER_REVIEWS',average:4.5,count:2},reviews:[{id:'22222222-2222-4222-8222-222222222222',stars:5,firstName:'<img literal>',comment:'Lovely gift',usedOn:null,submittedAt:'2026-10-06T10:00:00.000Z',verifiedCustomer:true,orderId:'private',phone:'private'}]};
test('only real verified review contract and customer fields survive',()=>{const result=validateReviews(raw);assert.equal(result.rating.average,4.5);assert.equal(result.reviews[0].firstName,'<img literal>');assert.equal('phone'in result.reviews[0],false);assert.equal('orderId'in result.reviews[0],false);});
test('fabricated, malformed or unverified ratings are rejected',()=>{assert.throws(()=>validateReviews({...raw,rating:{...raw.rating,source:'MANUAL'}}));assert.throws(()=>validateReviews({...raw,rating:{...raw.rating,average:6}}));assert.throws(()=>validateReviews({...raw,reviews:[{...raw.reviews[0],verifiedCustomer:false}]}));assert.throws(()=>validateReviews({...raw,rating:{source:'VERIFIED_ORDER_REVIEWS',average:5,count:0}}));assert.deepEqual(validateReviews({rating:{source:'VERIFIED_ORDER_REVIEWS',average:null,count:0},reviews:[]}).reviews,[]);});
